class MagicDictionary:
    def __init__(self):
        self.words = []

    def build_dict(self, dictionary):
        self.words = dictionary                                    # simple storage; small constraints allow direct scan

    def search(self, search_word):
        for w in self.words:
            if len(w) != len(search_word):
                continue
            diff = 0
            for a, b in zip(w, search_word):
                if a != b:
                    diff += 1
                    if diff > 1:
                        break                                          # early exit: too many mismatches
            if diff == 1:
                return True
        return False

