import java.util.*;

class MagicDictionary {
    List<String> words = new ArrayList<>();

    void buildDict(String[] dictionary) {
        words = Arrays.asList(dictionary);
    }

    boolean search(String searchWord) {
        for (String w : words) {
            if (w.length() != searchWord.length()) continue;
            int diff = 0;
            for (int i = 0; i < w.length(); i++) {
                if (w.charAt(i) != searchWord.charAt(i)) {
                    diff++;
                    if (diff > 1) break;                                  // early exit: too many mismatches
                }
            }
            if (diff == 1) return true;
        }
        return false;
    }
}

